    const lb = nb?.span?.start ?? Number.POSITIVE_INFINITY;
    if (la !== lb) return la - lb;
    return (na?.qualifiedName ?? na?.name ?? a) < (nb?.qualifiedName ?? nb?.name ?? b) ? -1 : 1;
  };

